-- has_role: from 20260426085840_07ed6e8c-239a-4baa-935d-e78c5a297fb5.sql; body md5 4e852b30ef52ba5263c4e11d1aec8cf0
CREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role public.app_role)
RETURNS BOOLEAN
LANGUAGE sql
