-- admin_group_module_submissions: from 20260926072000_fix_caller_identity_bypass.sql; body md5 408b67434cde2493c262f878a3597a41
create or replace function public.admin_group_module_submissions(p_caller_profile_id uuid default null::uuid, p_group_id uuid default null::uuid)
returns table(group_id uuid, module_id uuid, module_position integer, module_title text, total_students integer, submitted_count integer)
language plpgsql
stable
security definer
set search_path to 'public'
as $fx$
DECLARE
  -- THE FIX, in the exact shape this repo already shipped for the sibling function
  -- (20260820090000_harden_group_analytics_rpcs.sql:39-43). A REAL authenticated identity always
  -- wins; only the trusted service_role backend may assert an identity via the parameter; anything
  -- else resolves to NULL and is rejected below.
  -- Note the ordering matters even though every caller today behaves the same either way: preferring
  -- auth.uid() FIRST means a future service_role caller that also forwards a user JWT cannot assert
  -- someone else's identity. Matching the house pattern rather than inventing a second one.
  v_caller uuid := CASE
                     WHEN auth.uid() IS NOT NULL THEN auth.uid()
                     WHEN auth.role() = 'service_role' THEN p_caller_profile_id
                     ELSE NULL
                   END;
  v_is_admin boolean := false;
  v_is_teacher boolean := false;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_caller AND role = 'admin') INTO v_is_admin;
  SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_caller AND role = 'teacher') INTO v_is_teacher;
  IF NOT (v_is_admin OR v_is_teacher) THEN RAISE EXCEPTION 'forbidden'; END IF;
  RETURN QUERY
  WITH allowed_groups AS (
    SELECT g.id, g.course_id FROM public.groups g
    WHERE (v_is_admin OR g.teacher_id = v_caller)
      AND (p_group_id IS NULL OR g.id = p_group_id)
  ),
  group_totals AS (
    SELECT p.group_id, COUNT(*)::int AS total_students
    FROM public.profiles p
    WHERE p.group_id IN (SELECT id FROM allowed_groups) AND p.archived_at IS NULL
    GROUP BY p.group_id
  ),
  group_modules AS (
    SELECT ag.id AS group_id, m.id AS module_id, m.position AS module_position, m.title AS module_title
    FROM allowed_groups ag JOIN public.modules m ON m.course_id = ag.course_id
  )
  SELECT gm.group_id, gm.module_id, gm.module_position, gm.module_title,
    COALESCE(gt.total_students, 0)::int AS total_students,
    (
      SELECT COUNT(DISTINCT p.id)::int FROM public.profiles p
      WHERE p.group_id = gm.group_id AND p.archived_at IS NULL
        AND EXISTS (
          SELECT 1 FROM public.homework_submissions hs
          JOIN public.homework_assignments ha ON ha.id = hs.assignment_id
          WHERE hs.user_id = p.id AND ha.module_id = gm.module_id AND ha.is_active = true
        )
    ) AS submitted_count
  FROM group_modules gm
  LEFT JOIN group_totals gt ON gt.group_id = gm.group_id
  ORDER BY gm.group_id, gm.module_position;
END;
$fx$;

-- teacher_group_top: from 20260820100000_harden_per_user_rpcs.sql; body md5 366b6472d9cbd0fc846ac5392736849e
CREATE OR REPLACE FUNCTION public.teacher_group_top(uid uuid, _group_id uuid, _limit integer DEFAULT 5)
 RETURNS TABLE(rank integer, first_name text, last_initial text, total_xp integer, level integer, current_streak integer, completed_lessons integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
as $fx$
  with ok as (
    select exists(
      select 1 from groups g
      where g.id = _group_id
        and (g.teacher_id = uid or has_role(auth.uid(), 'admin'::app_role) or has_role(auth.uid(), 'superadmin'::app_role))
    ) and (auth.role() = 'service_role' or auth.uid() = uid
           or has_role(auth.uid(), 'admin'::app_role) or has_role(auth.uid(), 'superadmin'::app_role)) as allowed
  ),
  members as (
    select p.id, p.name, p.last_name
    from profiles p
    where p.group_id = _group_id and p.status = 'active' and p.archived_at is null
      and (select allowed from ok)
  ),
  ranked as (
    select m.id, m.name, m.last_name,
           coalesce(x.total_xp, 0) txp, coalesce(x.level, 1) lvl, coalesce(s.current_streak, 0) streak,
           row_number() over (order by coalesce(x.total_xp,0) desc, coalesce(s.current_streak,0) desc, m.id) r
    from members m
    left join user_xp x on x.user_id = m.id
    left join streaks s on s.user_id = m.id
  )
  select r.r::int, coalesce(nullif(r.name,''),'Talaba'), coalesce(left(nullif(r.last_name,''),1),''),
         r.txp, r.lvl, r.streak,
         (select count(*)::int from lesson_progress lp where lp.user_id = r.id and lp.completed_at is not null)
  from ranked r
  order by r.r
  limit _limit;
$fx$;

-- admin_export_group_csv: from 20260505205706_d33849d1-8aef-429a-ad39-d85546417272.sql; body md5 0bb5a39080b3f470f5405e41d49d085a
CREATE OR REPLACE FUNCTION public.admin_export_group_csv(_group_id uuid, _include_archived boolean DEFAULT false)
RETURNS TABLE(
  id uuid,
  name text,
  last_name text,
  email text,
  telegram_user_id bigint,
  telegram_username citext,
  role text,
  group_name text,
  first_login_at timestamptz,
  last_login_at timestamptz,
  has_logged_in boolean,
  lessons_completed integer,
  homework_avg numeric,
  status user_status,
  created_at timestamptz
)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
as $fx$
BEGIN
  IF NOT (
    public.has_role(auth.uid(),'admin'::app_role)
    OR EXISTS (SELECT 1 FROM public.groups g WHERE g.id = _group_id AND g.teacher_id = auth.uid())
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.name,
    p.last_name,
    p.email,
    p.telegram_id AS telegram_user_id,
    p.telegram_username,
    COALESCE(
      (SELECT ur.role::text FROM public.user_roles ur
        WHERE ur.user_id = p.id
        ORDER BY CASE ur.role WHEN 'admin' THEN 1 WHEN 'teacher' THEN 2 ELSE 3 END
        LIMIT 1),
      'student'
    ) AS role,
    g.name AS group_name,
    (SELECT MIN(ae.created_at) FROM public.auth_events ae WHERE ae.user_id = p.id AND ae.event = 'sign_in') AS first_login_at,
    u.last_sign_in_at AS last_login_at,
    (u.last_sign_in_at IS NOT NULL) AS has_logged_in,
    COALESCE((SELECT COUNT(*)::int FROM public.lesson_progress lp WHERE lp.user_id = p.id AND lp.completed_at IS NOT NULL), 0) AS lessons_completed,
    (SELECT ROUND(AVG(hs.score)::numeric, 2) FROM public.homework_submissions hs WHERE hs.user_id = p.id AND hs.score IS NOT NULL) AS homework_avg,
    p.status,
    p.created_at
  FROM public.profiles p
  LEFT JOIN auth.users u ON u.id = p.id
  LEFT JOIN public.groups g ON g.id = p.group_id
  WHERE p.group_id = _group_id
    AND (_include_archived OR (p.status = 'active' AND p.archived_at IS NULL));
END;
$fx$;

-- admin_dashboard_students: from 20260613100000_admin_dashboard_students_rpc.sql; body md5 b5588f00d420a8fcbe759c74a63ba33f
CREATE OR REPLACE FUNCTION public.admin_dashboard_students(_course_id uuid, _since30 timestamptz)
RETURNS TABLE(
  id uuid,
  name text,
  last_name text,
  telegram_username citext,
  telegram_id bigint,
  email text,
  created_at timestamptz,
  last_sign_in_at timestamptz,
  last_auth_at timestamptz,
  last_lesson_at timestamptz,
  logins_30d int,
  course_completed boolean
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path = public
as $fx$
DECLARE
  uid uuid := auth.uid();
  is_admin boolean;
  is_teacher boolean;
  total_lessons int;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'forbidden'; END IF;
  is_admin := public.has_role(uid, 'admin'::app_role) OR public.has_role(uid, 'superadmin'::app_role);
  is_teacher := public.has_role(uid, 'teacher'::app_role);
  IF NOT (is_admin OR is_teacher) THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT count(*) INTO total_lessons
  FROM public.lessons l
  JOIN public.modules m ON m.id = l.module_id
  WHERE m.course_id = _course_id AND l.published;

  RETURN QUERY
  SELECT
    p.id, p.name, p.last_name, p.telegram_username, p.telegram_id, p.email, p.created_at,
    u.last_sign_in_at,
    (SELECT max(ae.created_at) FROM public.auth_events ae
       WHERE ae.user_id = p.id AND ae.created_at >= _since30),
    (SELECT max(lp.updated_at) FROM public.lesson_progress lp
       WHERE lp.user_id = p.id AND lp.updated_at >= _since30),
    (SELECT count(*)::int FROM public.auth_events ae
       WHERE ae.user_id = p.id AND ae.created_at >= _since30 AND ae.event IN ('sign_in','login')),
    (total_lessons > 0 AND (
       SELECT count(DISTINCT lp.lesson_id) FROM public.lesson_progress lp
       JOIN public.lessons l ON l.id = lp.lesson_id
       JOIN public.modules m ON m.id = l.module_id
       WHERE lp.user_id = p.id AND m.course_id = _course_id AND l.published AND lp.completed_at IS NOT NULL
     ) >= total_lessons)
  FROM public.profiles p
  LEFT JOIN auth.users u ON u.id = p.id
  WHERE p.status = 'active'
    AND p.archived_at IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.user_roles ur
      WHERE ur.user_id = p.id
        AND ur.role IN ('admin'::app_role, 'superadmin'::app_role, 'teacher'::app_role)
    )
    AND (
      is_admin
      OR (is_teacher AND p.group_id IN (SELECT g.id FROM public.groups g WHERE g.teacher_id = uid))
    )
  ORDER BY p.created_at DESC;
END;
$fx$;

-- staff_recent_auth_events: from 20260502222446_c87c8936-ce0d-4622-937d-43e0c7f504e3.sql; body md5 9259b47f6108b106a2bd73965f63f96b
CREATE OR REPLACE FUNCTION public.staff_recent_auth_events(_since timestamptz)
RETURNS TABLE(user_id uuid, created_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public
as $fx$
DECLARE uid uuid := auth.uid();
DECLARE is_admin_user boolean := public.has_role(uid, 'admin'::app_role);
DECLARE is_teacher_user boolean := public.has_role(uid, 'teacher'::app_role);
BEGIN
  IF NOT (is_admin_user OR is_teacher_user) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF is_admin_user THEN
    RETURN QUERY SELECT e.user_id, e.created_at FROM public.auth_events e WHERE e.created_at >= _since LIMIT 50000;
  ELSE
    RETURN QUERY
      SELECT e.user_id, e.created_at FROM public.auth_events e
      WHERE e.created_at >= _since
        AND e.user_id IN (SELECT p.id FROM public.profiles p WHERE p.group_id IN (SELECT g.id FROM public.groups g WHERE g.teacher_id = uid))
      LIMIT 50000;
  END IF;
END;
$fx$;

-- staff_recent_lesson_progress: from 20260502222446_c87c8936-ce0d-4622-937d-43e0c7f504e3.sql; body md5 1f77cf8273ba4e35b7d31348d3dd8b80
CREATE OR REPLACE FUNCTION public.staff_recent_lesson_progress(_since timestamptz)
RETURNS TABLE(user_id uuid, lesson_id uuid, updated_at timestamptz, completed_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public
as $fx$
DECLARE uid uuid := auth.uid();
DECLARE is_admin_user boolean := public.has_role(uid, 'admin'::app_role);
DECLARE is_teacher_user boolean := public.has_role(uid, 'teacher'::app_role);
BEGIN
  IF NOT (is_admin_user OR is_teacher_user) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF is_admin_user THEN
    RETURN QUERY SELECT lp.user_id, lp.lesson_id, lp.updated_at, lp.completed_at
                 FROM public.lesson_progress lp WHERE lp.updated_at >= _since LIMIT 100000;
  ELSE
    RETURN QUERY
      SELECT lp.user_id, lp.lesson_id, lp.updated_at, lp.completed_at
      FROM public.lesson_progress lp
      WHERE lp.updated_at >= _since
        AND lp.user_id IN (SELECT p.id FROM public.profiles p WHERE p.group_id IN (SELECT g.id FROM public.groups g WHERE g.teacher_id = uid))
